from collections import deque

def can_reach_edge(r, c, grid, obstacles=None):
    """Can cell (r,c) reach any grid edge without passing through obstacles"""
    if obstacles is None:
        obstacles = set()

    h, w = len(grid), len(grid[0])
    queue = deque([(r, c)])
    visited = {(r, c)}

    while queue:
        cr, cc = queue.popleft()
        # Check if we've reached an edge
        if cr == 0 or cr == h-1 or cc == 0 or cc == w-1:
            return True

        for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
            nr, nc = cr+dr, cc+dc
            if (nr, nc) not in visited:
                if 0 <= nr < h and 0 <= nc < w:
                    if grid[nr][nc] == 0 and (nr, nc) not in obstacles:
                        visited.add((nr, nc))
                        queue.append((nr, nc))

    return False

