def find_sandwiches(r, c, grid):
    """Check if cell at (r,c) is sandwiched horizontally or vertically"""
    h_sand = False
    v_sand = False

    # Horizontal sandwich
    if grid[r][c] == 0:
        left_5 = right_5 = None
        for col in range(len(grid[r])):
            if grid[r][col] == 5:
                if left_5 is None:
                    left_5 = col
                else:
                    right_5 = col
                    break
        if left_5 is not None and right_5 is not None and c > left_5 and c < right_5:
            h_sand = True

    # Vertical sandwich  
    if not h_sand and grid[r][c] == 0:
        above_5 = below_5 = None
        for row_idx in range(len(grid)):
            if grid[row_idx][c] == 5:
