                q = deque([(r,c)])
                region_cells = []
                visited = {(r,c)}
                while q:
                    cr, cc = q.popleft()
                    region_cells.append((cr, cc))
                    for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
                        nr, nc = cr+dr, cc+dc
                        if (nr, nc) not in visited:
                            if 0 <= nr < h and 0 <= nc < w and grid[nr][nc] == 0:
